export const localBusinessSchema = (pagePath = "/") => ({
  "@context": "https://schema.org",
  "@type": "RoofingContractor",
  "@id": `${SITE_URL}/#business`,
  name: BUSINESS.name,
  alternateName: ["Bravo Roofing", "Bravo Roofing Idaho"],
  url: `${SITE_URL}/`,
  mainEntityOfPage: `${SITE_URL}${pagePath}`,
  image: `${SITE_URL}/project-boise-83713.jpg`,
  telephone: "+1-208-515-9425",
  email: BUSINESS.email,
  foundingDate: "2021",
  address: {
    "@type": "PostalAddress",
    addressLocality: "Nampa",
    addressRegion: "ID",
    addressCountry: "US",
  },
  areaServed: SERVICE_CITIES.map((city) => ({
    "@type": "City",
    name: `${city.name}, ID`,
  })),
  hasOfferCatalog: {
    "@type": "OfferCatalog",
    name: "Roofing services",
    itemListElement: OFFERED_SERVICES.map((name) => ({
      "@type": "Offer",
      itemOffered: { "@type": "Service", name },
    })),
  },
  sameAs: [
    PROFILE_LINKS.facebook,
    PROFILE_LINKS.instagram,
    PROFILE_LINKS.bbb,
    PROFILE_LINKS.gaf,
  ],
});

export const faqSchema = (faqs: Array<{ question: string; answer: string }>) => ({
  "@context": "https://schema.org",
  "@type": "FAQPage",
  mainEntity: faqs.map((faq) => ({
    "@type": "Question",
    name: faq.question,
    acceptedAnswer: { "@type": "Answer", text: faq.answer },
  })),
});

export const breadcrumbSchema = (crumbs: Array<{ name: string; path: string }>) => ({
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  itemListElement: crumbs.map((crumb, index) => ({
    "@type": "ListItem",
    position: index + 1,
    name: crumb.name,
    item: `${SITE_URL}${crumb.path}`,
  })),
});
